/**
 * Tests for dsh-probstat. All numeric anchors are generated by the independent
 * Python oracle test/oracle/anchors.py (math.erf / math.comb exact primitives +
 * bisection + independent t and Wilson implementations) and cross-validated
 * against published z-table and t-table values.
 *
 * ORACLE: test/oracle/anchors.py
 *
 * Discipline: every result object is checked with assertNoUndefined (lossless
 * JSON gate), and argument helpers only assign keys that are present.
 *
 * @module dsh-probstat/test
 */

import { describe, expect, it } from 'vitest'
import { buildProbstatTools } from '../src/tools.ts'
import { twoSampleTest } from '../src/core.ts'
import { normalCdf, normalQuantile, tQuantile } from '../src/math.ts'

/* ------------------------------------------------------------------ */
/* helpers                                                             */
/* ------------------------------------------------------------------ */

/** Recursive lossless-JSON discipline check: no key may hold undefined. */
function assertNoUndefined(value: unknown, path = 'root'): void {
  if (value === undefined) {
    throw new Error(`undefined live key at ${path}`)
  }
  if (Array.isArray(value)) {
    value.forEach((item, index) => assertNoUndefined(item, `${path}[${index}]`))
  } else if (value !== null && typeof value === 'object') {
    for (const [key, item] of Object.entries(value as Record<string, unknown>)) {
      assertNoUndefined(item, `${path}.${key}`)
    }
  }
}

/** Build args with only defined keys (args-side lossless JSON discipline). */
function pick(entries: Record<string, unknown>): Record<string, unknown> {
  const result: Record<string, unknown> = {}
  for (const [key, value] of Object.entries(entries)) {
    if (value !== undefined) result[key] = value
  }
  return result
}

const tools = buildProbstatTools()
const executeDist = tools.dist_calc.execute as (args: Record<string, unknown>) => Promise<Record<string, unknown>>
const executeZ = tools.z_score.execute as (args: Record<string, unknown>) => Promise<Record<string, unknown>>
const executeCi = tools.confidence_interval.execute as (args: Record<string, unknown>) => Promise<Record<string, unknown>>
const executeEvent = tools.event_probability.execute as (args: Record<string, unknown>) => Promise<Record<string, unknown>>
const executeTest = tools.hypothesis_test.execute as (args: Record<string, unknown>) => Promise<Record<string, unknown>>
const executeSample = tools.sample_size.execute as (args: Record<string, unknown>) => Promise<Record<string, unknown>>
const renderTest = tools.hypothesis_test.output.render as (args: unknown, value: unknown) => Array<{ type: string; text: string }>
const renderSample = tools.sample_size.output.render as (args: unknown, value: unknown) => Array<{ type: string; text: string }>

/* ------------------------------------------------------------------ */
/* math primitives — oracle anchors                                     */
/* ------------------------------------------------------------------ */

describe('normal distribution', () => {
  it('cdf matches the independent oracle (published z-table values)', () => {
    expect(normalCdf(1.96, 0, 1)).toBeCloseTo(0.9750021, 6)
    expect(normalCdf(2.576, 0, 1)).toBeCloseTo(0.9950025, 6)
    expect(normalCdf(0, 0, 1)).toBeCloseTo(0.5, 12)
    expect(normalCdf(-1, 0, 1)).toBeCloseTo(0.1586553, 6)
    expect(normalCdf(5, 2, 3)).toBeCloseTo(normalCdf(1, 0, 1), 6) // standardize
  })

  it('quantile matches the independent oracle (published z-table values)', () => {
    expect(normalQuantile(0.975, 0, 1)).toBeCloseTo(1.959964, 6)
    expect(normalQuantile(0.95, 0, 1)).toBeCloseTo(1.6448536, 7)
    expect(normalQuantile(0.025, 0, 1)).toBeCloseTo(-1.959964, 6)
    expect(normalQuantile(0.995, 0, 1)).toBeCloseTo(2.5758293, 7)
    expect(normalQuantile(0.5, 0, 1)).toBeCloseTo(0, 9)
  })

  it('quantile inverts cdf across the range', () => {
    for (const p of [0.001, 0.01, 0.05, 0.1, 0.3, 0.5, 0.7, 0.9, 0.95, 0.99, 0.999]) {
      const z = normalQuantile(p, 0, 1)
      expect(normalCdf(z, 0, 1)).toBeCloseTo(p, 5)
    }
  })
})

describe('binomial distribution', () => {
  it('matches the independent oracle (exact summation via math.comb)', async () => {
    let r = await executeDist(pick({ distribution: 'binomial', operation: 'pdf', n: 10, p: 0.5, x: 3 }))
    expect(r.result).toBeCloseTo(0.1171875, 12)
    r = await executeDist(pick({ distribution: 'binomial', operation: 'cdf', n: 10, p: 0.5, x: 3 }))
    expect(r.result).toBeCloseTo(0.171875, 12)
    r = await executeDist(pick({ distribution: 'binomial', operation: 'cdf', n: 20, p: 0.3, x: 5 }))
    expect(r.result).toBeCloseTo(0.4163708, 7)
    r = await executeDist(pick({ distribution: 'binomial', operation: 'survival', n: 5, p: 0.2, x: 1 }))
    expect(r.result).toBeCloseTo(0.26272, 6)
  })

  it('quantile matches the independent oracle', async () => {
    let r = await executeDist(pick({ distribution: 'binomial', operation: 'quantile', n: 10, p: 0.5, q: 0.5 }))
    expect(r.result).toBe(5)
    r = await executeDist(pick({ distribution: 'binomial', operation: 'quantile', n: 20, p: 0.4, q: 0.95 }))
    expect(r.result).toBe(12)
  })

  it('stats are closed-form np / np(1-p)', async () => {
    const r = await executeDist(pick({ distribution: 'binomial', operation: 'stats', n: 20, p: 0.4 }))
    expect(r.mean).toBeCloseTo(8, 12)
    expect(r.variance).toBeCloseTo(4.8, 12)
    expect(r.sd).toBeCloseTo(2.1908902, 7)
  })

  it('edge cases: p=0 and p=1', async () => {
    let r = await executeDist(pick({ distribution: 'binomial', operation: 'cdf', n: 5, p: 0, x: 0 }))
    expect(r.result).toBe(1)
    r = await executeDist(pick({ distribution: 'binomial', operation: 'pdf', n: 5, p: 0, x: 0 }))
    expect(r.result).toBe(1)
    r = await executeDist(pick({ distribution: 'binomial', operation: 'pdf', n: 5, p: 1, x: 5 }))
    expect(r.result).toBe(1)
    r = await executeDist(pick({ distribution: 'binomial', operation: 'cdf', n: 5, p: 1, x: 4 }))
    expect(r.result).toBe(0)
  })
})

describe('poisson distribution', () => {
  it('matches the independent oracle', async () => {
    let r = await executeDist(pick({ distribution: 'poisson', operation: 'pdf', lambda: 3, x: 2 }))
    expect(r.result).toBeCloseTo(0.2240418, 7)
    r = await executeDist(pick({ distribution: 'poisson', operation: 'cdf', lambda: 3, x: 2 }))
    expect(r.result).toBeCloseTo(0.4231901, 7)
    r = await executeDist(pick({ distribution: 'poisson', operation: 'cdf', lambda: 4.5, x: 5 }))
    expect(r.result).toBeCloseTo(0.7029304, 7)
    r = await executeDist(pick({ distribution: 'poisson', operation: 'survival', lambda: 2, x: 3 }))
    expect(r.result).toBeCloseTo(0.1428765, 7)
  })

  it('quantile matches the independent oracle', async () => {
    let r = await executeDist(pick({ distribution: 'poisson', operation: 'quantile', lambda: 3, q: 0.5 }))
    expect(r.result).toBe(3)
    r = await executeDist(pick({ distribution: 'poisson', operation: 'quantile', lambda: 10, q: 0.99 }))
    expect(r.result).toBe(18)
  })

  it('stats: mean = variance = lambda', async () => {
    const r = await executeDist(pick({ distribution: 'poisson', operation: 'stats', lambda: 4.5 }))
    expect(r.mean).toBeCloseTo(4.5, 12)
    expect(r.variance).toBeCloseTo(4.5, 12)
    expect(r.sd).toBeCloseTo(2.1213203, 7)
  })
})

describe('exponential distribution', () => {
  it('matches the independent oracle', async () => {
    let r = await executeDist(pick({ distribution: 'exponential', operation: 'pdf', lambda: 0.5, x: 1 }))
    expect(r.result).toBeCloseTo(0.3032653, 7)
    r = await executeDist(pick({ distribution: 'exponential', operation: 'cdf', lambda: 0.5, x: 1 }))
    expect(r.result).toBeCloseTo(0.3934693, 7)
    r = await executeDist(pick({ distribution: 'exponential', operation: 'survival', lambda: 0.5, x: 2 }))
    expect(r.result).toBeCloseTo(0.3678794, 7)
    r = await executeDist(pick({ distribution: 'exponential', operation: 'quantile', lambda: 0.5, q: 0.5 }))
    expect(r.result).toBeCloseTo(1.3862944, 7)
  })

  it('x < 0 gives zero density / zero cdf / unit survival with a note', async () => {
    const r = await executeDist(pick({ distribution: 'exponential', operation: 'cdf', lambda: 1, x: -1 }))
    expect(r.result).toBe(0)
    expect(r.note).toBeDefined()
  })
})

describe('uniform distribution', () => {
  it('matches the independent oracle', async () => {
    let r = await executeDist(pick({ distribution: 'uniform', operation: 'pdf', a: 0, b: 3, x: 1.5 }))
    expect(r.result).toBeCloseTo(0.3333333, 7)
    r = await executeDist(pick({ distribution: 'uniform', operation: 'cdf', a: 0, b: 3, x: 2 }))
    expect(r.result).toBeCloseTo(0.6666667, 7)
    r = await executeDist(pick({ distribution: 'uniform', operation: 'cdf', a: 0, b: 3, x: -1 }))
    expect(r.result).toBe(0)
    r = await executeDist(pick({ distribution: 'uniform', operation: 'quantile', a: 2, b: 6, q: 0.25 }))
    expect(r.result).toBe(3)
  })

  it('stats: mean (a+b)/2, variance (b-a)^2/12', async () => {
    const r = await executeDist(pick({ distribution: 'uniform', operation: 'stats', a: 2, b: 6 }))
    expect(r.mean).toBe(4)
    expect(r.variance).toBeCloseTo(1.3333333, 7)
  })
})

describe('geometric distribution (failures before first success)', () => {
  it('matches the independent oracle', async () => {
    let r = await executeDist(pick({ distribution: 'geometric', operation: 'pdf', p: 0.3, x: 2 }))
    expect(r.result).toBeCloseTo(0.147, 9)
    r = await executeDist(pick({ distribution: 'geometric', operation: 'cdf', p: 0.3, x: 2 }))
    expect(r.result).toBeCloseTo(0.657, 9)
    r = await executeDist(pick({ distribution: 'geometric', operation: 'survival', p: 0.25, x: 1 }))
    expect(r.result).toBeCloseTo(0.5625, 9)
    r = await executeDist(pick({ distribution: 'geometric', operation: 'quantile', p: 0.5, q: 0.5 }))
    expect(r.result).toBe(0)
    expect(r.note).toBeDefined()
  })

  it('stats: mean (1-p)/p, variance (1-p)/p^2', async () => {
    const r = await executeDist(pick({ distribution: 'geometric', operation: 'stats', p: 0.25 }))
    expect(r.mean).toBe(3)
    expect(r.variance).toBe(12)
  })
})

