describe('z_score tool', () => {
  it('to_prob matches the independent oracle', async () => {
    const r = await executeZ(pick({ mode: 'to_prob', z: 1.96 }))
    expect(r.probability).toBeCloseTo(0.9750021, 6)
    expect(r.percentile).toBeCloseTo(97.50021, 4)
    expect(r.percentile).toBeCloseTo((r.probability as number) * 100, 9)
  })

  it('from_prob matches the independent oracle', async () => {
    const r = await executeZ(pick({ mode: 'from_prob', p: 0.975 }))
    expect(r.z).toBeCloseTo(1.959964, 6)
    expect(r.percentile).toBeCloseTo(97.5, 6)
  })

  it('two_sided matches the independent oracle', async () => {
    let r = await executeZ(pick({ mode: 'two_sided', z: 1.96 }))
    expect(r.pValue).toBeCloseTo(0.0499958, 6)
    r = await executeZ(pick({ mode: 'two_sided', z: 2 }))
    expect(r.pValue).toBeCloseTo(0.0455003, 6)
  })

  it('between matches the independent oracle and sorts the bounds', async () => {
    const r = await executeZ(pick({ mode: 'between', z1: -1, z2: 1 }))
    expect(r.probability).toBeCloseTo(0.6826895, 6)
    const swapped = await executeZ(pick({ mode: 'between', z1: 1, z2: -1 }))
    expect(swapped.probability).toBeCloseTo(0.6826895, 6)
    expect(swapped.z1).toBe(-1)
    expect(swapped.z2).toBe(1)
  })

  it('rejects out-of-range p', async () => {
    const r = await executeZ(pick({ mode: 'from_prob', p: 1 }))
    expect(r.valid).toBe(false)
    expect(r.error).toBeDefined()
  })
})

