describe('confidence_interval tool', () => {
  it('mean_z matches the independent oracle', async () => {
    const r = await executeCi(pick({ kind: 'mean_z', mean: 100, sigma: 15, n: 30 }))
    expect(r.lower).toBeCloseTo(94.6324176, 7)
    expect(r.upper).toBeCloseTo(105.3675824, 7)
    expect(r.marginOfError).toBeCloseTo(5.3675824, 7)
    expect(r.criticalValue).toBeCloseTo(1.959964, 6)
    expect(r.standardError).toBeCloseTo(2.7386128, 7)
  })

  it('mean_t matches the independent oracle (published t-table: 2.201 at df=11)', async () => {
    const r = await executeCi(pick({ kind: 'mean_t', mean: 5, sd: 1.5, n: 12 }))
    expect(r.lower).toBeCloseTo(4.0469455, 7)
    expect(r.upper).toBeCloseTo(5.9530545, 7)
    expect(r.marginOfError).toBeCloseTo(0.9530545, 7)
    expect(r.criticalValue).toBeCloseTo(2.2009852, 6)
  })

  it('proportion matches the independent oracle (Wilson interval)', async () => {
    let r = await executeCi(pick({ kind: 'proportion', successes: 40, n: 100 }))
    expect(r.lower).toBeCloseTo(0.3094013, 7)
    expect(r.upper).toBeCloseTo(0.4979974, 7)
    r = await executeCi(pick({ kind: 'proportion', successes: 0, n: 50 }))
    expect(r.lower).toBeCloseTo(0, 9)
    expect(r.upper).toBeCloseTo(0.0713476, 7)
    r = await executeCi(pick({ kind: 'proportion', successes: 50, n: 50 }))
    expect(r.lower).toBeCloseTo(0.9286524, 7)
    expect(r.upper).toBeCloseTo(1, 9)
  })

  it('rejects bad inputs with a clear error', async () => {
    let r = await executeCi(pick({ kind: 'mean_t', mean: 5, sd: 1.5, n: 1 }))
    expect(r.valid).toBe(false)
    r = await executeCi(pick({ kind: 'proportion', successes: 7, n: 5 }))
    expect(r.valid).toBe(false)
  })
})

