describe('event_probability tool', () => {
  it('union (independent and mutually exclusive)', async () => {
    let r = await executeEvent(pick({ operation: 'union', pA: 0.3, pB: 0.4 }))
    expect(r.result).toBeCloseTo(0.58, 9)
    expect(r.formula).toBeDefined()
    r = await executeEvent(pick({ operation: 'union', pA: 0.3, pB: 0.4, independent: false }))
    expect(r.result).toBeCloseTo(0.7, 9)
  })

  it('intersection (independent)', async () => {
    const r = await executeEvent(pick({ operation: 'intersection', pA: 0.3, pB: 0.4 }))
    expect(r.result).toBeCloseTo(0.12, 9)
  })

  it('intersection without independence is refused', async () => {
    const r = await executeEvent(pick({ operation: 'intersection', pA: 0.3, pB: 0.4, independent: false }))
    expect(r.valid).toBe(false)
  })

  it('conditional', async () => {
    const r = await executeEvent(pick({ operation: 'conditional', pIntersection: 0.2, pCondition: 0.5 }))
    expect(r.result).toBeCloseTo(0.4, 9)
  })

  it('bayes matches the independent oracle (classic medical test example)', async () => {
    const r = await executeEvent(pick({ operation: 'bayes', prior: 0.01, truePositive: 0.99, falsePositive: 0.05 }))
    expect(r.result).toBeCloseTo(0.1666667, 7)
  })

  it('complement and at_least_one', async () => {
    let r = await executeEvent(pick({ operation: 'complement', p: 0.25 }))
    expect(r.result).toBeCloseTo(0.75, 9)
    r = await executeEvent(pick({ operation: 'at_least_one', p: 0.1, n: 5 }))
    expect(r.result).toBeCloseTo(0.40951, 6)
  })

  it('rejects invalid probabilities', async () => {
    let r = await executeEvent(pick({ operation: 'complement', p: 1.5 }))
    expect(r.valid).toBe(false)
    r = await executeEvent(pick({ operation: 'bayes', prior: 1, truePositive: 0, falsePositive: 0 }))
    expect(r.valid).toBe(false)
  })
})

