describe('hypothesis_test tool', () => {
  it('mean_z (known sigma) matches the independent oracle', async () => {
    const r = await executeTest(pick({ kind: 'mean_z', sampleMean: 102, mu0: 100, sigma: 15, n: 36 }))
    expect(r.statistic).toBeCloseTo(0.8, 12)
    expect(r.standardError).toBeCloseTo(2.5, 12)
    expect(r.pValue).toBeCloseTo(0.4237108, 6)
    expect(r.pValueTwoSided).toBeCloseTo(0.4237108, 6)
    expect(r.pValueLeft).toBeCloseTo(0.7881446, 6)
    expect(r.pValueRight).toBeCloseTo(0.2118554, 6)
    expect(r.criticalValue).toBeCloseTo(1.959964, 6)
    expect(r.alpha).toBe(0.05)
    expect(r.reject).toBe(false)
    expect(r.df).toBeUndefined()
  })

  it('mean_z honours the requested tail and the critical value follows it', async () => {
    const r = await executeTest(pick({ kind: 'mean_z', sampleMean: 102, mu0: 100, sigma: 15, n: 36, tail: 'right' }))
    expect(r.pValue).toBeCloseTo(0.2118554, 6)
    expect(r.criticalValue).toBeCloseTo(1.6448536, 6)

    const l = await executeTest(pick({ kind: 'mean_z', sampleMean: 100, mu0: 103, sigma: 10, n: 25, tail: 'left' }))
    expect(l.statistic).toBeCloseTo(-1.5, 12)
    expect(l.pValue).toBeCloseTo(0.0668072, 6)
    expect(l.criticalValue).toBeCloseTo(-1.6448536, 6)
    expect(l.reject).toBe(false)
  })

  it('mean_t uses df = n - 1 and Student-t p-values (oracle)', async () => {
    const r = await executeTest(pick({ kind: 'mean_t', sampleMean: 5.2, mu0: 5, sd: 1.5, n: 12, tail: 'right' }))
    expect(r.statistic).toBeCloseTo(0.4618802, 7)
    expect(r.standardError).toBeCloseTo(0.4330127, 7)
    expect(r.df).toBe(11)
    expect(r.pValue).toBeCloseTo(0.3265839, 6)
    expect(r.pValueTwoSided).toBeCloseTo(0.6531677, 6)
    expect(r.criticalValue).toBeCloseTo(1.7958848, 6)

    const two = await executeTest(pick({ kind: 'mean_t', sampleMean: 5.2, mu0: 5, sd: 1.5, n: 12 }))
    expect(two.criticalValue).toBeCloseTo(2.2009852, 6)
  })

  it('proportion uses p0 in the standard error and rejects at alpha = 0.05', async () => {
    const r = await executeTest(pick({ kind: 'proportion', successes: 40, n: 100, p0: 0.5 }))
    expect(r.statistic).toBeCloseTo(-2, 12)
    expect(r.standardError).toBeCloseTo(0.05, 12)
    expect(r.pValue).toBeCloseTo(0.0455003, 6)
    expect(r.pValueLeft).toBeCloseTo(0.0227501, 6)
    expect(r.criticalValue).toBeCloseTo(1.959964, 6)
    expect(r.reject).toBe(true)

    const hi = await executeTest(pick({ kind: 'proportion', successes: 62, n: 100, p0: 0.5, tail: 'right' }))
    expect(hi.statistic).toBeCloseTo(2.4, 12)
    expect(hi.pValue).toBeCloseTo(0.0081975, 6)
  })

  it('flags an unreliable normal approximation instead of hiding it', async () => {
    const r = await executeTest(pick({ kind: 'proportion', successes: 1, n: 10, p0: 0.1 }))
    expect(r.valid).toBe(true)
    expect(String(r.note)).toContain('normal approximation')
    expect(String(r.note)).toContain('n*p0 = 1')

    const solid = await executeTest(pick({ kind: 'proportion', successes: 40, n: 100, p0: 0.5 }))
    expect(solid.note).toBeUndefined()
  })

  it('rejects bad inputs with a clear error', async () => {
    let r = await executeTest(pick({ kind: 'mean_z', sampleMean: 1, sigma: 1, n: 4 }))
    expect(r.valid).toBe(false)
    r = await executeTest(pick({ kind: 'mean_z', sampleMean: 1, mu0: 0, sigma: 0, n: 4 }))
    expect(r.valid).toBe(false)
    r = await executeTest(pick({ kind: 'mean_t', sampleMean: 1, mu0: 0, sd: 1, n: 1 }))
    expect(r.valid).toBe(false)
    r = await executeTest(pick({ kind: 'proportion', successes: 7, n: 5, p0: 0.5 }))
    expect(r.valid).toBe(false)
    r = await executeTest(pick({ kind: 'proportion', successes: 2, n: 10, p0: 0 }))
    expect(r.valid).toBe(false)
    r = await executeTest(pick({ kind: 'mean_z', sampleMean: 1, mu0: 0, sigma: 1, n: 4, alpha: 0 }))
    expect(r.valid).toBe(false)
  })

  it('renders the decision in the tool text', async () => {
    const value = await executeTest(pick({ kind: 'proportion', successes: 40, n: 100, p0: 0.5 }))
    const [block] = renderTest({}, value)
    expect(block.type).toBe('text')
    expect(block.text).toContain('reject the null hypothesis')
    expect(block.text).toContain('critical value')

    const failed = renderTest({}, { valid: false, error: 'boom' })
    expect(failed[0].text).toContain('boom')
  })
})

