describe('sample_size tool', () => {
  it('mean_z matches the independent oracle (with the ceiling applied)', async () => {
    const r = await executeSample(pick({ kind: 'mean_z', sigma: 15, marginOfError: 5 }))
    expect(r.criticalValue).toBeCloseTo(1.959964, 6)
    expect(r.nExact).toBeCloseTo(34.573129, 6)
    expect(r.n).toBe(35)
    expect(r.conf).toBe(0.95)

    const tight = await executeSample(pick({ kind: 'mean_z', sigma: 15, marginOfError: 5, conf: 0.99 }))
    expect(tight.criticalValue).toBeCloseTo(2.5758293, 6)
    expect(tight.nExact).toBeCloseTo(59.71407, 5)
    expect(tight.n).toBe(60)
  })

  it('proportion with the Wald closed form (explicit and default p)', async () => {
    const r = await executeSample(pick({ kind: 'proportion', p: 0.5, marginOfError: 0.03 }))
    expect(r.method).toBe('wald')
    expect(r.nExact).toBeCloseTo(1067.0719, 4)
    expect(r.n).toBe(1068)
    expect(r.assumedP).toBe(0.5)

    const q = await executeSample(pick({ kind: 'proportion', p: 0.2, marginOfError: 0.05 }))
    expect(q.nExact).toBeCloseTo(245.8534, 4)
    expect(q.n).toBe(246)

    const dflt = await executeSample(pick({ kind: 'proportion', marginOfError: 0.03 }))
    expect(dflt.assumedP).toBe(0.5)
    expect(String(dflt.note)).toContain('worst case')
  })

  it('proportion with the Wilson method returns the smallest n meeting the target', async () => {
    const r = await executeSample(pick({ kind: 'proportion', p: 0.5, marginOfError: 0.03, method: 'wilson' }))
    expect(r.method).toBe('wilson')
    expect(r.n).toBe(1064)
    expect(String(r.note)).toContain('Wilson')

    const q = await executeSample(pick({ kind: 'proportion', p: 0.2, marginOfError: 0.05, method: 'wilson' }))
    expect(q.n).toBe(245)
  })

  it('rejects impossible targets and bad inputs', async () => {
    let r = await executeSample(pick({ kind: 'proportion', p: 0.5, marginOfError: 0, method: 'wilson' }))
    expect(r.valid).toBe(false)
    r = await executeSample(pick({ kind: 'proportion', p: 0.5, marginOfError: 1e-6, method: 'wilson' }))
    expect(r.valid).toBe(false)
    expect(String(r.error)).toContain('no sample size up to')
    r = await executeSample(pick({ kind: 'mean_z', sigma: 0, marginOfError: 5 }))
    expect(r.valid).toBe(false)
    r = await executeSample(pick({ kind: 'proportion', p: 1, marginOfError: 0.03 }))
    expect(r.valid).toBe(false)
    r = await executeSample(pick({ kind: 'proportion', p: 0.5, marginOfError: 0.03, conf: 1 }))
    expect(r.valid).toBe(false)
  })

  it('renders the required n in the tool text', async () => {
    const value = await executeSample(pick({ kind: 'mean_z', sigma: 15, marginOfError: 5 }))
    const [block] = renderSample({}, value)
    expect(block.text).toContain('required n: 35')
    expect(block.text).toContain('critical value')

    const failed = renderSample({}, { valid: false, error: 'boom' })
    expect(failed[0].text).toContain('boom')
  })
})

/* ------------------------------------------------------------------ */
/* discipline: lossless JSON + validation                              */
/* ------------------------------------------------------------------ */

describe('discipline checks', () => {
  it('every result tree is free of undefined live keys', async () => {
    const cases: Promise<Record<string, unknown>>[] = [
      executeDist(pick({ distribution: 'normal', operation: 'cdf', x: 1.5 })),
      executeDist(pick({ distribution: 'normal', operation: 'stats' })),
      executeDist(pick({ distribution: 'binomial', operation: 'quantile', n: 10, p: 0.5, q: 0.5 })),
      executeDist(pick({ distribution: 'exponential', operation: 'cdf', lambda: 1, x: -1 })),
      executeDist(pick({ distribution: 'geometric', operation: 'cdf', p: 0.3, x: 2 })),
      executeDist(pick({ distribution: 'normal', operation: 'cdf' })),
      executeZ(pick({ mode: 'between', z1: -1, z2: 1 })),
      executeCi(pick({ kind: 'mean_z', mean: 100, sigma: 15, n: 30 })),
      executeCi(pick({ kind: 'proportion', successes: 40, n: 100 })),
      executeEvent(pick({ operation: 'bayes', prior: 0.01, truePositive: 0.99, falsePositive: 0.05 })),
      executeTest(pick({ kind: 'mean_z', sampleMean: 102, mu0: 100, sigma: 15, n: 36 })),
      executeTest(pick({ kind: 'mean_t', sampleMean: 5.2, mu0: 5, sd: 1.5, n: 12 })),
      executeTest(pick({ kind: 'proportion', successes: 1, n: 10, p0: 0.1 })),
      executeTest(pick({ kind: 'mean_z', sampleMean: 1, sigma: 1, n: 4 })),
      executeSample(pick({ kind: 'mean_z', sigma: 15, marginOfError: 5 })),
      executeSample(pick({ kind: 'proportion', marginOfError: 0.03 })),
      executeSample(pick({ kind: 'proportion', p: 0.5, marginOfError: 0.03, method: 'wilson' })),
      executeSample(pick({ kind: 'proportion', p: 0.5, marginOfError: 1e-6, method: 'wilson' })),
    ]
    for (const result of await Promise.all(cases)) {
      assertNoUndefined(result)
    }
  })

  it('invalid enum values are rejected at the schema layer', async () => {
    await expect(executeDist(pick({ distribution: 'bogus', operation: 'cdf', x: 1 }))).rejects.toThrow()
    await expect(executeDist(pick({ distribution: 'normal', operation: 'bogus', x: 1 }))).rejects.toThrow()
    await expect(executeZ(pick({ mode: 'bogus' }))).rejects.toThrow()
    await expect(executeCi(pick({ kind: 'bogus' }))).rejects.toThrow()
    await expect(executeEvent(pick({ operation: 'bogus' }))).rejects.toThrow()
    await expect(executeTest(pick({ kind: 'anova' }))).rejects.toThrow()
    await expect(executeTest(pick({ kind: 'mean_z', sampleMean: 1, mu0: 0, sigma: 1, n: 4, tail: 'both' }))).rejects.toThrow()
    await expect(executeSample(pick({ kind: 'median', marginOfError: 0.03 }))).rejects.toThrow()
    await expect(executeSample(pick({ kind: 'proportion', p: 0.5, marginOfError: 0.03, method: 'exact' }))).rejects.toThrow()
  })

  it('missing required properties are rejected at the schema layer', async () => {
    await expect(executeSample(pick({ kind: 'mean_z', sigma: 15 }))).rejects.toThrow(/marginOfError/)
    await expect(executeSample(pick({ kind: 'mean_z' }))).rejects.toThrow(/marginOfError/)
  })

  it('validation errors carry valid=false and a message, never undefined keys', async () => {
    const r = await executeDist(pick({ distribution: 'normal', operation: 'quantile', q: 2 }))
    expect(r.valid).toBe(false)
    expect(typeof r.error).toBe('string')
    assertNoUndefined(r)
  })

  it('default operation is cdf and default normal is standard', async () => {
    const r = await executeDist(pick({ distribution: 'normal', x: 1.96 }))
    expect(r.operation).toBe('cdf')
    expect(r.result).toBeCloseTo(0.9750021, 6)
  })
})

